/* Official current-brand wordmarks (Google Pay, PhonePe, Paytm, BHIM), traced from
 * a user-supplied reference image and re-exported with a transparent background at
 * ~3x the print size these chips render at, so they stay crisp and match each app's
 * current-2026 branding instead of the outdated flat-color marks this file used to carry.
 */
export type PaymentBrandId = "gpay" | "phonepe" | "paytm" | "bhim";
export const PAYMENT_BRAND_LOGOS: Record<PaymentBrandId, { dataUrl: string; aspect: number }> = {
  gpay: { dataUrl: "data:image/png;base64,", aspect: 2.2857142857142856 },
  phonepe: { dataUrl: "data:image/png;base64,", aspect: 3.902439024390244 },
  paytm: { dataUrl: "data:image/png;base64,", aspect: 2.807017543859649 },
  bhim: { dataUrl: "data:image/png;base64,", aspect: 3.595505617977528 },
};

/* Official NPCI "UPI" mark (wordmark + tricolour arrow), cropped from a
 * user-supplied reference image and re-exported with a transparent
 * background and no surrounding padding, so it can be dropped straight
 * into the receipt header and scaled to the header's height without
 * carrying extra whitespace that would force it to overflow the strip. */
export const UPI_MARK_LOGO: { dataUrl: string; aspect: number } = {
  dataUrl: "data:image/png;base64,",
  aspect: 219 / 82,
};
